:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #f0f0f5;
  --accent: #6c5ce7;
  --hunger: #e17055;
  --happiness: #00b894;
  --energy: #0984e3;
  --bar-bg: #3a3a55;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
}

h1 {
  font-size: 1.75rem;
  letter-spacing: 1px;
}

/* Pixel pet */
.pet {
  width: 120px;
  height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.pet-body {
  position: relative;
  width: 80px;
  height: 80px;
  background: var(--accent);
  border-radius: 12px;
  box-shadow: 0 0 0 8px #4a3f8a;
  animation: bounce 2s infinite ease-in-out;
}

@keyframes bounce {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-6px); }
}

.eye {
  position: absolute;
  top: 24px;
  width: 12px;
  height: 12px;
  background: #fff;
  border-radius: 50%;
}

.eye.left { left: 16px; }
.eye.right { right: 16px; }

.eye::after {
  content: '';
  position: absolute;
  top: 4px;
  left: 4px;
  width: 4px;
  height: 4px;
  background: #1e1e2f;
  border-radius: 50%;
}

.mouth {
  position: absolute;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  width: 24px;
  height: 8px;
  background: #fff;
  border-radius: 0 0 12px 12px;
}

/* Mood text */
.mood {
  font-size: 1.1rem;
  font-weight: 600;
  text-align: center;
  min-height: 1.5em;
}

/* Stats */
.stats {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-label {
  font-size: 0.95rem;
  font-weight: 500;
  opacity: 0.9;
}

.bar {
  height: 16px;
  background: var(--bar-bg);
  border-radius: 8px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  width: 100%;
  border-radius: 8px;
  transition: width 0.4s ease;
}

.bar-fill.hunger { background: var(--hunger); }
.bar-fill.happiness { background: var(--happiness); }
.bar-fill.energy { background: var(--energy); }

/* Controls */
.controls {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
  width: 100%;
}

button {
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 20px;
  border: none;
  border-radius: 8px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s, box-shadow 0.2s;
  flex: 1 1 auto;
  min-width: 80px;
}

button:hover {
  background: #7d6ff0;
}

button:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

button:active {
  transform: scale(0.96);
  background: #5a4bd1;
}

@media (max-width: 360px) {
  .card { padding: 24px 16px; }
  button { padding: 10px 12px; font-size: 0.95rem; }
}

const state = {
  hunger: 100,
  happiness: 100,
  energy: 100
};

const moodEl = document.getElementById('mood');
const hungerBar = document.getElementById('hunger-bar');
const happinessBar = document.getElementById('happiness-bar');
const energyBar = document.getElementById('energy-bar');

function clamp(value) {
  return Math.max(0, Math.min(100, value));
}

function updateMood() {
  const avg = (state.hunger + state.happiness + state.energy) / 3;
  if (avg >= 80) {
    moodEl.textContent = "I'm feeling great!";
  } else if (avg >= 50) {
    moodEl.textContent = "I'm doing okay.";
  } else if (avg >= 25) {
    moodEl.textContent = "I need some attention...";
  } else {
    moodEl.textContent = "I'm not feeling well...";
  }
}

function render() {
  hungerBar.style.width = state.hunger + '%';
  happinessBar.style.width = state.happiness + '%';
  energyBar.style.width = state.energy + '%';
  updateMood();
}

function feed() {
  state.hunger = clamp(state.hunger + 15);
  state.energy = clamp(state.energy + 5);
  state.happiness = clamp(state.happiness + 5);
  render();
}

function play() {
  state.happiness = clamp(state.happiness + 15);
  state.energy = clamp(state.energy - 10);
  state.hunger = clamp(state.hunger - 5);
  render();
}

function sleep() {
  state.energy = clamp(state.energy + 20);
  state.hunger = clamp(state.hunger - 5);
  state.happiness = clamp(state.happiness - 5);
  render();
}

document.getElementById('feed-btn').addEventListener('click', feed);
document.getElementById('play-btn').addEventListener('click', play);
document.getElementById('sleep-btn').addEventListener('click', sleep);

// Passive decay every 5 seconds
setInterval(() => {
  state.hunger = clamp(state.hunger - 2);
  state.happiness = clamp(state.happiness - 1);
  state.energy = clamp(state.energy - 1);
  render();
}, 5000);

render();
